architecture.h4_f:
msg = CBOR{v:1, текст, отговор_на, изпратен_на}
ct = AES-GCM-256-Шифроване(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, текст, reply_to?, thread_id?, споменавания?, sent_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
проводник = CBOR{
  v: 1,
  шифрован текст: hex(ct), // променлива дължина
  nonce: шестнадесетичен (12 B),
  sender_pseudo: шестнадесетичен (16 B),
  изпратен_в: unix_ms
}

cryptoWire.h5_f:
външен = CBOR{
  източник_възел: hex32,
  target_user: int64,
  inner_ciphertext: байтове,
  inner_nonce: байтове,
  изпратен_в: unix_ms
}
sig = Ed25519-Sign(source_priv, външен)
POST /federation/deliver { envelope: outer, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { потребителско име, парола, x25519_публичен_ключ, показвано_име, телефон?, имейл?, avatar_emoji }

Отговор 201 Създаден:
  { access_token, refresh_token, user_id, username, ...}

auth.h3_f:
access_token полезен товар:
  { sub: user_id, jti: device_id, typ: "достъп", exp: сега + 15 минути }
refresh_token полезен товар:
  { sub: user_id, jti: device_id, typ: "refresh", exp: сега + 30d }

HS256-подписано с 64-байтов секрет на възел от .env

auth.h4_f:
register_begin(): предизвикателство = rand(32)
                    опции = {rp.id, user.id, pubKeyCredParams, предизвикателство}
                    опции за връщане

register_finish(атестация):
  проверете атестацията срещу TPM / Secure Enclave root CA
  store {credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR payload = { nonce, user_id, сървър: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → регистрирано ново устройство; JWT се върнаха.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 шестнадесетичен
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Разклоняваща се рамка: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {име на файл, размер, chunk_size_hint}
            ← {upload_id, chunk_size}
парче PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct байта>
            ← 204
финализиране POST /api/files/resumable/{upload_id}/финализиране {plain_blake3}
            ← 201 {file_id, url}
TTL на недовършен: 24 ч

files.h4_f:
deny_list = {
  "приложение/x-dosexec",
  "приложение/x-sharedlib",
  "приложение/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) в deny_list: върне 415

presence.h1_f:
клиент: при първото натискане на клавиш → изпрати {type:"t", state:"start"}
         няма повече изпращания за 3 s, освен ако състоянието не се промени
         10 s след последното натискане на клавиш → изпрати {type:"t", state:"stop"}
приемник: автоматично спиране 10 s след последния "старт", ако не е пристигнало "стоп".

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS излъчване {type:"c", kind:"invite", call_id}
WS излъчване {type:"c", kind:"offer", sdp}
WS излъчване {type:"c", kind:"answer", sdp}
WS излъчване {type:"c", kind:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
плик = {
  източник_възел: hex32,
  target_user: int64,
  inner_ciphertext: байтове,
  inner_nonce: байтове,
  изпратен_в: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(плик))
POST /federation/deliver { envelope, sig }

gossip.h3_f:
реклама = {pubkey, крайна точка, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(реклама))
полезен товар за клюки: [..., {ad, sig}, ...]

приемник: проверете sig срещу ad.pubkey → съхранявайте, ако е добре
допълнително: PoW от 2^18 водещи нули на {pubkey, endpoint}

stealth.h2_f:
ClientHello байтове = chrome_120_template с {
  случайно = нашето произволно,
  server_name = нашето име на хост (или ECH-опаковано),
  session_id = идентификаторът на нашата сесия,
}
JA4 = t13d_xxxx_xxxx_xxxx (съвпада с текущата стабилна версия на Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {име: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(публичен_ключ_от_HTTPS_запис)
DGA: домейн(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data)}
Уеб SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
инструмент = знак_инструмент
вход = дърво на източника, ключове/release.key
манифест = {
  версия: "0.1.0",
  build_at: unix_ms,
  файлове: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(манифест))
изход = INTEGRITY.sig.json = {манифест, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
създайте: POST /api/bots {потребителско име, показвано_име, код}
          → {bot_id, token, pubkey}
изпълнение: в процес (съпрограма вътре в възел)
      OR външен (long-poll /api/bots/{id}/updates, token-auth'd)
съобщение: {текст, подпис: Ed25519-Sign(bot_priv, canonical_msg)}

